scenarios.example_code:
import { reportCrash } from '@projexlight/sdk-diagnostic-telemetry';
await reportCrash({
  tenant_id, persona_id, app_version: '3.2.1',
  platform: 'ios', stack: '...', context: { route: '/dispatch/route', last_action: 'route-materialize' },
});

import { computeHealthSnapshot } from '@projexlight/sdk-diagnostic-telemetry';
const snap = await computeHealthSnapshot({ tenant_id, period: '2026-05-26T15:00Z' });
// snap = { app_version_3_2_1_ios_crash_rate: 0.08, baseline: 0.005 }

// frames captured passively by the client SDK (rate-limited + redacted):
import { captureReplayFrame } from '@projexlight/sdk-diagnostic-telemetry';
await captureReplayFrame({
  tenant_id, persona_id, ui_state: { route, form_state },
});
